// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class NpcTreasureIcon : MonoBehaviour
{
	[SerializeField]
	private GameObject mContent;

	[SerializeField]
	private ImageProxy mNpcIcon;

	[SerializeField]
	private Button mBtn;

	[SerializeField]
	private WorldStateSwitcher<bool> mIconColorStates;

	private int mTreasureClassId;


    private IPartnerTreasureIconServices services;
    public void Configure(IPartnerTreasureIconServices value)
    { services = value ?? throw new System.ArgumentNullException(nameof(value)); }

	private void OnEnable()
	{


		((UnityEvent)mBtn.onClick).AddListener((UnityAction)OnClick);
	}

	private void OnDisable()
	{


		((UnityEvent)mBtn.onClick).RemoveListener((UnityAction)OnClick);
	}

	private void OnDestroy()
	{
		mNpcIcon.Clear();
	}

	public void RefleshNpcTreasureInfo(int treasureClassId)
	{
		mTreasureClassId = treasureClassId;
		mNpcIcon.Clear();
		mContent.SetActive(false);
		if (treasureClassId > 0)
		{
			IProfessionItemInfo itemInfo = services.GetItemInfo(treasureClassId);
			if (itemInfo != null)
			{
				mNpcIcon.Load(itemInfo.Icon);
				bool flag = services.IsTreasureActive(treasureClassId);
				mIconColorStates.SetState(flag);
				services.SetUIGray(mNpcIcon.GameObject, !flag);
				mContent.SetActive(true);
			}
		}
	}

	private void OnClick()
	{
		if (mTreasureClassId > 0)
		{
			services.PopupTreasureDetail(mTreasureClassId);
		}
	}
}

}
